template:
use std::sync::atomic::{AtomicU32, Ordering::SeqCst};
static LOG: AtomicU32 = AtomicU32::new(0);

fn push(v: u32) {
    LOG.store(LOG.load(SeqCst) * 10 + v, SeqCst);
}

struct Guard;
impl Guard {
    fn enter() -> Self { push(1); Guard }
}
impl Drop for Guard {
    fn drop(&mut self) { push(2); }
}

fn do_work() {
    let ⟦slot1⟧ = Guard::enter();
    ⟦slot2⟧;
}

tests:
#[test]
fn test_guard_order() {
    LOG.store(0, SeqCst);
    do_work();
    assert_eq!(LOG.load(SeqCst), 132);
}
